import { ServerClient } from "postmark";

let client: ServerClient | undefined;

// Server-only. Created lazily so the app still builds and runs without a token.
export function getPostmark(): ServerClient | undefined {
  const token = process.env.POSTMARK_SERVER_TOKEN;
  if (!token) return undefined;
  client ??= new ServerClient(token);
  return client;
}
EOF
cat > src/lib/email.ts <<'EOF'
import { getPostmark } from "@/lib/postmark";

type Message = { to: string; subject: string; html: string; text: string };

function escapeHtml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

// Never throws: a failed email must not break the request that triggered it.
async function send({ to, subject, html, text }: Message): Promise<boolean> {
  const postmark = getPostmark();
  const from = process.env.POSTMARK_FROM_EMAIL;
  if (!postmark || !from) {
    console.warn(`[email] Postmark not configured; skipped "${subject}" to ${to}`);
    return false;
  }
  try {
    await postmark.sendEmail({
      From: from,
      To: to,
      Subject: subject,
      HtmlBody: html,
      TextBody: text,
      MessageStream: process.env.POSTMARK_MESSAGE_STREAM || "outbound",
    });
    return true;
  } catch (err) {
    console.error(`[email] failed to send "${subject}" to ${to}:`, err);
    return false;
  }
}

export function sendWelcomeEmail(user: { email: string; name: string }) {
  const name = escapeHtml(user.name);
  return send({
    to: user.email,
    subject: "Welcome to Notely",
    html: `<p>Hi ${name},</p><p>Welcome to Notely! Your account is ready.</p>`,
    text: `Hi ${user.name},\n\nWelcome to Notely! Your account is ready.`,
  });
}

export function sendPasswordResetEmail(
  user: { email: string; name: string },
  resetUrl: string,
) {
  const name = escapeHtml(user.name);
  const url = escapeHtml(resetUrl);
  return send({
    to: user.email,
    subject: "Reset your Notely password",
    html: `<p>Hi ${name},</p><p><a href="${url}">Reset your password</a>. This link expires in 1 hour.</p><p>If you didn't ask for this, you can ignore this email.</p>`,
    text: `Hi ${user.name},\n\nReset your password: ${resetUrl}\n\nThis link expires in 1 hour. If you didn't ask for this, ignore this email.`,
  });
}
EOF
cat >> src/lib/users.ts <<'EOF'

export async function createUser(input: {
  email: string;
  name: string;
}): Promise<User> {
  const email = input.email.trim().toLowerCase();
  if (users.some((u) => u.email === email)) {
    throw new Error("A user with this email already exists");
  }
  const user: User = {
    id: String(users.length + 1),
    email,
    name: input.name.trim(),
    createdAt: new Date().toISOString().slice(0, 10),
  };
  users.push(user);
  await sendWelcomeEmail(user);
  return user;
}

const RESET_TTL_MS = 60 * 60 * 1000;
// Only a hash of each token is stored, keyed by hash.
const resetTokens = new Map<string, { userId: string; expiresAt: number }>();

const hashToken = (token: string) =>
  createHash("sha256").update(token).digest("hex");

// Always resolves the same way whether or not the email exists, so callers can't
// use it to discover which addresses have accounts.
export async function requestPasswordReset(email: string): Promise<void> {
  const normalized = email.trim().toLowerCase();
  const user = users.find((u) => u.email === normalized);
  if (!user) return;
  const token = randomBytes(32).toString("base64url");
  resetTokens.set(hashToken(token), {
    userId: user.id,
    expiresAt: Date.now() + RESET_TTL_MS,
  });
  const base = process.env.APP_URL ?? "http://localhost:3000";
  await sendPasswordResetEmail(
    user,
    `${base}/reset-password?token=${encodeURIComponent(token)}`,
  );
}

// Single-use. Returns the user the token belongs to, or undefined if invalid/expired.
// Setting the new password is left to the future auth work (there are no passwords yet).
export async function consumePasswordResetToken(
  token: string,
): Promise<User | undefined> {
  const key = hashToken(token);
  const entry = resetTokens.get(key);
  resetTokens.delete(key);
  if (!entry || entry.expiresAt < Date.now()) return undefined;
  return getUser(entry.userId);
}
EOF
